  "plans.eyebrow": "Плани та функції",
  "plans.title": "Порівняти плани StockHaven",
  "plans.intro": "Один обліковий запис, який би план ви не обрали — Business охоплює до п'яти бізнесів. Ціни вказано щомісячно в доларах США, а нові клієнти вебсайту, які відповідають умовам, можуть отримати один семиденний пробний період для Essentials і Business. Оновлення наявної підписки Essentials до Business не перезапускає пробний період і не створює ще один безкоштовний пробний період. Ціни планів для вебсайту вказані до застосовних податків, якщо такі є. Ваше точне стягнення буде показано, перш ніж ви дозволите підписку.",
