  "plans.mobileIncludedNote": "Обидва плани для вебсайту включають мобільний помічник, тож передплатник вебсайту ніколи не платить також щомісячну плату за мобільну версію.",
  "plans.priceNote": "Essentials коштує $14.99/місяць плюс застосовні податки, якщо такі є. Business коштує $29.99/місяць плюс застосовні податки, якщо такі є. Будь-який необхідний податок визначається під час оплати у постачальника і має з'явитися в остаточній сумі перед платежем. Ця сторінка порівняння не є розрахунком податку чи дозволом на платіж.",
  "plans.mobilePriceNote": "План лише для мобільних пристроїв коштує $4.99/місяць за передбаченою базовою ціною для США. App Store або Google Play показує фактичну місцеву ціну підписки та будь-які застосовні податки перед покупкою. Його ліміти товарів, місць і персоналу встановлюються під час запуску, окремо від рівнів вебсайту.",
  "plans.planChangeNote": "Зміну плану вебсайту має підтвердити постачальник платежів. Нову ціну, дату набрання чинності та будь-який перерахунок буде пояснено, перш ніж зміну буде дозволено. Оновлення не повинно створювати другу підписку.",
  "plans.providerNote": "Ціни, стягнення та пробні періоди обробляє постачальник, через якого ви підписуєтеся — App Store, Google Play, вебсайт або Shopify — ніколи не ця сторінка.",
