  "upgrade.upgradeNeverRestartsTrial": "Оновлення ніколи не перезапускає ваш безкоштовний пробний період.",
  "upgrade.trialHistoryNote": "Якщо ви платите за Essentials і переходите на Business, ви зберігаєте той самий обліковий запис клієнта та історію пробних періодів. Business не включає додатковий семиденний пробний період. Якщо ви оновлюєте, поки ваш початковий пробний період ще триває, його початкова дата завершення не скидається.",
  "upgrade.providerConfirmNote": "Зміни плану потребують підтвердження від постачальника платежів. Будь-яку різницю в ціні, перерахунок і дату набрання чинності має бути показано, перш ніж ви схвалите зміну. Оновлення не повинно створювати другу одночасну підписку.",
  "upgrade.chargedThroughProviderNote": "Зміни плану стягуються через постачальника платежів. Ви можете скасувати підписку з цієї сторінки за допомогою кнопки «Скасувати підписку» під вашим поточним планом або в налаштуваннях. Скасування зупиняє майбутні поновлення наприкінці вашого оплаченого періоду; воно ніколи не завершує ваш доступ одразу. Наявні безкоштовні робочі простори не стягуються за перегляд цих параметрів.",
