  "billing.cancel.yourPlan": "ваш план",
  "billing.cancel.doneTitle": "Вашу підписку скасовано.",
  "billing.cancel.doneWithEnd": "Ви зберігаєте повний доступ до {endDate}. Після цієї дати у вас є пільговий період лише для читання тривалістю {graceDays} днів — ви все ще можете входити й бачити свої товари, але не можете нічого додавати, редагувати, видаляти, сканувати, імпортувати, експортувати чи змінювати. {gracePart}",
  "billing.cancel.graceEndsOn": "Після того, як 15-денний пільговий період завершиться {date}, ваш обліковий запис і всю його інформацію буде назавжди видалено без можливості відновлення.",
  "billing.cancel.doneNoEnd": "Ви зберігаєте повний доступ до кінця вашого оплаченого періоду. Після цього застосовується 15-денний пільговий період лише для читання. {wipeSentence}",
  "billing.cancel.refundWindowOpen": "Ви скасували протягом 3 днів після вашого першого оплаченого стягнення, тож ви можете мати право на повернення цього першого платежу. Скасування саме по собі не здійснює повернення — запросіть його через {contact}.",
  "billing.cancel.refundWindowClosed": "Скасування саме по собі не здійснює повернення. Повернення застосовується лише протягом 3 днів після першого успішного оплаченого стягнення, за запитом через {contact}.",
  "billing.cancel.notCanceledTitle": "Вашу підписку НЕ було скасовано.",
  "billing.cancel.contactCode": "Якщо ви звернетеся до {contact}, зазначте цей код: {code}",
  "billing.cancel.alreadyCanceledTitle": "Цю підписку вже скасовано.",
  "billing.cancel.alreadyCanceledWithEnd": "Вона завершується {date}. Ви зберігаєте повний доступ до того часу. Після цієї дати у вас є пільговий період лише для читання тривалістю {graceDays} днів, щоб бачити свої товари. {wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "Вона завершується наприкінці поточного оплаченого періоду. Ви зберігаєте повний доступ до того часу.",
  "billing.cancel.appStoreNote": "Якщо ви коли-небудь підпишетеся через Google Play або Apple App Store, вам може знадобитися скасувати її в налаштуваннях підписок цього магазину. Це діалогове вікно не може зупинити виставлення рахунків магазину застосунків. Видалення застосунку або видалення вашого облікового запису StockHaven не скасовує підписку магазину.",
  "billing.cancel.trialNote": "Скасування під час пробного періоду зберігає ваші повні 7 днів — доступ завершується {date}, і з вас не стягуватимуть плату.",
  "billing.cancel.trialNoteNoDate": "Скасування під час пробного періоду зберігає ваші повні 7 днів, і з вас не стягуватимуть плату.",
  "billing.cancel.keepAccessUntil": "Ви зберігаєте повний доступ до {date}.",
  "billing.cancel.endOfPaidPeriod": "кінця вашого оплаченого періоду",
  "billing.cancel.keepAccessRest": "Скасування зупиняє лише майбутні поновлення — воно ніколи не завершує ваш доступ одразу, і жодного додаткового безкоштовного місяця не додається.",
  "billing.cancel.gracePeriodTitle": "Після цієї дати — пільговий період лише для читання тривалістю {graceDays} днів.",
  "billing.cancel.gracePeriodRest": "Ви все ще можете входити й бачити свої товари, тож можете подивитися, що у вас було, і записати це. Усе інше заблоковано: жодного додавання, редагування, видалення, сканування, імпортування, експортування чи перенесення, жодних налаштувань, жодного персоналу.",
  "billing.cancel.resubscribeFresh": "Повторна підписка починається з нуля.",
  "billing.cancel.refundsSeparate": "Повернення коштів — окремо.",
  "billing.cancel.refundsRest": "Скасування саме по собі не здійснює повернення. Повернення першого платежу застосовується лише, якщо ви скасуєте протягом 3 днів (72 годин) після першого успішного оплаченого стягнення, за запитом через {contact}.",
  "billing.cancel.oneTrialTitle": "Один безкоштовний пробний період.",
  "billing.cancel.oneTrialRest": "Скасування пробного періоду або підписки не надає ще один пробний період; клієнти, що повертаються, мають обрати платну підписку.",
  "billing.cancel.keepOrClose": "Залишити підписку / Закрити",
