  "billing.cancel.close": "Закрити",
  "billing.cancelError.methodNotAllowed": "Щось пішло не так з нашого боку. Нічого не було змінено — спробуйте знову або зверніться до служби підтримки.",
  "billing.cancelError.signInRequired": "Щоб скасувати, вам потрібно ввійти. Увійдіть і спробуйте знову.",
  "billing.cancelError.invalidRequest": "Ми не змогли визначити, яку підписку скасувати. Нічого не було змінено — спробуйте знову або зверніться до служби підтримки.",
  "billing.cancelError.businessIdRequired": "Ми не змогли визначити, яку підписку скасувати. Нічого не було змінено — спробуйте знову або зверніться до служби підтримки.",
  "billing.cancelError.subscriptionOwnerRequired": "Лише власник бізнесу може скасувати цю підписку. Нічого не було змінено.",
  "billing.cancelError.billingRecordsNeedReview": "Ваші платіжні записи потребують перевірки, перш ніж це можна буде скасувати. Нічого не було змінено — зверніться до служби підтримки.",
  "billing.cancelError.complimentaryAccessProtected": "Цей робочий простір має безкоштовний доступ, тож немає платної підписки для скасування. Нічого не було змінено.",
  "billing.cancelError.noVerifiedSubscriptionRecord": "Ми не змогли знайти підтверджену підписку для цього бізнесу. Нічого не було змінено — зверніться до служби підтримки.",
  "billing.cancelError.purchaseContractMismatch": "Платіжний запис не відповідає цьому бізнесу, тож ми не можемо скасувати його тут. Нічого не було змінено — зверніться до служби підтримки.",
  "billing.cancelError.stripeNotConfigured": "Не вдалося зв'язатися з платежами. Нічого не змінилося — спробуйте знову або зверніться до служби підтримки.",
  "billing.cancelError.subscriptionPaidThroughUnverified": "Ми не змогли підтвердити вашу дату, до якої оплачено. Нічого не було змінено — спробуйте знову або зверніться до служби підтримки.",
  "billing.cancelError.alreadyEnded": "Ця підписка вже завершилася, тож більше немає чого скасовувати.",
  "billing.cancelError.subscriptionEventHistoryIncomplete": "Ваша історія платежів потребує перевірки, перш ніж це можна буде скасувати. Нічого не було змінено — зверніться до служби підтримки.",
  "billing.cancelError.eventRequiresReview": "Ваша історія платежів потребує перевірки, перш ніж це можна буде скасувати. Нічого не було змінено — зверніться до служби підтримки.",
  "billing.cancelError.subscriptionCancellationUnavailable": "Скасування не вдалося завершити. Нічого не було змінено — ваша підписка та доступ залишилися точно такими, як були. Спробуйте знову або зверніться до служби підтримки.",
  "billing.readiness.ariaLabel": "Фактична готовність оплати Essentials",
  "billing.readiness.title": "Оплата Essentials — справжня перевірка безпеки облікового запису",
  "billing.readiness.body": "Перегляньте фактичні записи підписки та пробних періодів, нічого не купуючи. Ваш безкоштовний обліковий запис Business і ваш зразок піжами залишаються без змін. Це не відкриває оплату Stripe, не стягує картку й не змінює план.",
  "billing.readiness.checking": "Перевірка записів облікового запису…",
