  "billing.readiness.environmentIncomplete": "Не вдалося підтвердити всі облікові дані оплати Stripe, підтвердження вебгуків або зворотну адресу застосунку. Жодна оплата не може розпочатися.",
  "billing.readiness.ownerHasHistory": "Цей власник має попередні докази підписки або пробного періоду. Другу оплату не можна створювати.",
  "billing.readiness.trialAlreadyUsed": "Ознайомчий пробний період уже було використано або зарезервовано. Повторний пробний період не може розпочатися.",
  "billing.readiness.trialEligibilityUnverified": "Право на одноразовий пробний період не підтверджено для цього власника. Оплата залишається заблокованою.",
  "billing.readiness.testModeUnverified": "Записи облікового запису можна читати, але безпечне стримування тестового режиму Stripe та виконання платного поновлення не підтверджено. Оплата залишається заблокованою.",
