  "billing.readiness.catalogUnverified": "Затверджене серверне визначення оплати за $14.99/місяць потребує підтвердження.",
  "billing.readiness.auditUnavailable": "Перевірка сервера лише для читання була недоступна. Жодного платежу чи зміни облікового запису не відбулося.",
