  "billing.dryRun.preserved": "Ту саму підписку збережено, один початковий пробний період збережено, а змодельовані піжамні запаси без змін. Приклад клієнта залишається на Essentials, доки справжнє, підтверджене постачальником платне поновлення не виправдає зміну доступу.",
