  "exports.eyebrow": "Дані",
  "exports.title": "Експорт і резервні копії",
  "exports.subtitleStart": "Завантаження завжди обмежені лише",
  "exports.subtitleRest": ". Кожен файл позначено назвою бізнесу та датою його створення.",
  "exports.createBusinessFirst": "Спочатку створіть бізнес — експорт належить бізнесу, а не застосунку.",
  "exports.lockedTitle": "Експорт у CSV та Excel — це функція плану Business",
  "exports.lockedDesc": "Ваш робочий простір на плані Essentials. Business додає експорт у CSV та Excel, оцінку запасів, необмежену кількість товарів і персоналу, постачальників, закупівлі та комплекти.",
  "exports.seeBusiness": "Що включає Business",
  "exports.whatTheseAre": "Що це за файли",
  "exports.about1": "Кожен набір даних надається як CSV або справжня книга Excel (.xlsx) — повна книга запасів доступна лише в Excel, з окремим аркушем для кожного набору даних. Файли CSV відкриваються в Excel, Numbers, Google Sheets і більшості застосунків для обліку запасів. Текст UTF-8, коми в лапках, розриви рядків у примітках і початкові нулі в кодах — усе зберігається, а комірки, що починаються як формула, нейтралізуються, щоб таблиця відкривала їх як текст.",
  "exports.about2": "У файлах Excel коди SKU, UPC, ISBN і штрихкоди є текстовими комірками — ніколи не в експоненційному записі і ніколи без початкових нулів — із застосованою шириною стовпців, фільтрами заголовків і форматами валюти чи кількості. Повна книга запасів зберігає товари, рівні запасів, розташування та рухи на окремих аркушах.",
  "exports.about3": "Дуже великі експорти зупиняються на 20,000 рядків на набір даних — коли це стається, назва файлу про це каже (truncated-20000), щоб частковий файл ніколи не видавався за повний.",
  "exports.about4": "Резервна копія — це знімок ваших даних, а не відновлення в один клік. Її відновлення — це ручна робота з попереднім переглядом, тож зберігайте файл у безпеці — наразі нічого в застосунку не може відтворити з неї видалений бізнес. Код застосунку та резервні копії платформи Base44 обробляються окремо від цих файлів.",
  "exports.about5": "Фотографії та вкладення перелічено як їхні збережені посилання — самі файли зображень не пакуються в завантаження.",
  "exports.backupTitle": "Повна резервна копія",
  "exports.backupDesc": "Один файл із товарами цього бізнесу, розташуваннями, рівнями запасів, повним журналом рухів, постачальниками, закупівлями, замовленнями, поверненнями, підрахунками та оголошеннями — плюс налаштування його профілю. Зберігайте його там, де ви це контролюєте.",
  "exports.backupIncludes1": "Товари, коди, витрати та примітки",
  "exports.backupIncludes2": "Розташування та кількість за розташуванням",
  "exports.backupIncludes3": "Кожен рух, із виконавцем і часом",
  "exports.backupIncludes4": "Закупівлі, замовлення, повернення та підрахунки",
  "exports.buildingBackup": "Створення резервної копії…",
  "exports.backupJson": "Резервна копія (JSON)",
  "exports.excelSnapshot": "Знімок Excel",
