  "exports.rowsDone": "{count} рядків",
  "import.eyebrow": "Дані",
  "import.title": "Центр імпорту",
  "import.subtitleStart": "Три окремі операції з електронними таблицями, щоб виправлення ціни ніколи не могло надійти як надходження запасів. Усе потрапляє лише до",
  "import.subtitleRest": " , і нічого не записується, доки не пройде пробний запуск.",
  "import.createBusinessFirst": "Спочатку створіть бізнес — імпортовані товари належать бізнесу.",
  "import.createBusinessFirstShort": "Спочатку створіть бізнес.",
  "import.whatEachDoes": "Що робить кожна операція",
  "import.createTitle": "Створити нові товари",
  "import.createDesc": "додає рядки, яких ще немає в каталозі. Дубльовані SKU та штрихкоди, що вже використовуються, пропускаються, а початкові запаси можуть надійти до обраного вами розташування як надходження.",
  "import.updateTitle": "Оновити наявні товари",
  "import.updateDesc": "зіставляє кожен рядок за SKU або ID запису та показує старе значення поруч із запропонованим новим. Порожні комірки залишають збережене значення без змін, якщо ви не попросите очистити порожні, а кількості ніколи не змінюються.",
  "import.receiveModeTitle": "Отримати запаси",
  "import.receiveModeDesc": "додає кількості, що надходять, до одного розташування та записує надходження до журналу рухів для кожного рядка. Кожна партія позначається, щоб той самий аркуш не можна було отримати двічі.",
  "import.excelNote": "Книги Excel (.xlsx) читаються напряму — виберіть аркуш, і стовпці буде зіставлено за вас. Коди залишаються цілими: UPC, збережений як текст, зберігає свої цифри та початкові нулі. Рядки, які не можна імпортувати, перелічено з причиною",
  "import.excelNoteDownload": " і їх можна завантажити як файл.",
  "import.excelNoteFix": ", щоб ви могли їх виправити та спробувати ще раз.",
  "import.matchColumns": "Зіставте стовпці",
  "import.columnFallback": "Стовпець {column}",
  "import.ignoreColumn": "Ігнорувати цей стовпець",
  "import.mapNameRequired": "Зіставте один стовпець із назвою товару — кожен імпортований рядок потребує назви.",
  "import.receiveMissingMessage": "Зіставте стовпець із SKU або ID запису, а один — із отриманою кількістю.",
  "import.updateMissingMessage": "Зіставте стовпець із SKU або ID запису — кожен рядок знаходиться за одним із них.",
  "import.dryRunTitle": "Пробний запуск",
