  "print.supplierBlockedDesc": "Документи для постачальників входять до плану Business — постачальники, закупівлі та замовлення на закупівлю. Усе, що у вас є зараз, продовжує працювати.",
  "print.seeBusiness": "Що включає Business",
  "print.nothingToPrint": "Ще немає чого друкувати",
  "print.pickOrderHint": "Виберіть замовлення на закупівлю зі списку, щоб переглянути документ.",
  "print.pickCustomerOrderHint": "Виберіть замовлення клієнта зі списку, щоб переглянути документ.",
  "print.pickReturnHint": "Виберіть зареєстроване повернення зі списку, щоб переглянути документ.",
  "print.chooseStyleHint": "Виберіть стиль, потім виберіть товари зі списку. Попередній перегляд показує саме те, що вийде з принтера.",
  "print.howToReach": "Як підключитися до вашого принтера",
  "print.howIntro": "Цей застосунок підключається до принтерів, які у вас уже є — він сам не є принтером. Є чотири способи підключитися до нього, і етикетки друкуються на обох планах через будь-який із них. Пакувальні листи, замовлення на закупівлю, документи для постачальників і звіти доступні лише в Business, незалежно від підключення.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Із цієї сторінки, на настільному Chrome або Edge і на Android Chrome: виберіть ваш принтер етикеток, і етикетки підуть прямо до нього. Це не працює в iOS Safari — на iPhone друк через Bluetooth надається разом із мобільним застосунком. Принтер, який розмовляє лише мовою Zebra ZPL або власною мовою Brother, не зрозуміє етикетки, які надсилає ця сторінка; це перевіряється на справжніх принтерах, перш ніж це називати робочим.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Встановіть принтер у Wi-Fi вашого магазину, потім скористайтеся кнопкою Друк — він друкує через принтер, встановлений на цьому комп’ютері, через мережу магазину. На iPhone AirPrint вбудовано: принтер AirPrint на тому самому Wi-Fi просто з’являється в аркуші друку, без шнура та без застосунку, і застосунку не потрібен код, специфічний для AirPrint. Принтер має підтримувати AirPrint (більшість нових підтримують), а телефон і принтер мають бути на тому самому Wi-Fi.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Підключіть принтер до мережі вашого магазину шнуром Ethernet, встановіть його на комп’ютері та друкуйте через кнопку Друк. Ethernet — це шлях для настільних комп’ютерів і комп’ютерів — iPhone не використовують шнури Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Підключіть принтер до комп’ютера його шнуром і скористайтеся кнопкою Друк — він друкує через принтер, встановлений там. На телефоні Android із кабелем USB OTG кнопка USB вище розмовляє прямо з принтером. iPhone не можуть друкувати через USB напряму — там немає WebUSB — тож використовуйте Wi-Fi / AirPrint або Bluetooth із мобільного застосунку.",
  "print.howCordsLead": "Шнури все одно служать iPhone, на один крок віддалено.",
  "print.howCordsBody": "Принтер USB, підключений до комп’ютера магазину, або принтер Ethernet, підключений до мережі, з’являється на вашому iPhone через Wi-Fi магазину (AirPrint / спільний принтер) — шнури надійно підключають принтер до мережі, а телефон досягає його бездротово.",
  "print.howOfflineLead": "Якщо інтернет зникне,",
  "print.howOfflineBody": "етикетки та документи, уже на цій сторінці, все одно друкуються — кнопка Друк, PDF етикеток, Bluetooth і USB не потребують підключення. Що справді потребує інтернету, то це завантаження сторінки та її товарів насамперед. Повний офлайн-режим (робота в застосунку взагалі без підключення) — це окрема, більша розробка, і тут вона не заявляється.",
