  "settings.cancelSubscription": "Скасувати підписку",
  "settings.cancelTerms.appleLink": "Інструкції зі скасування Apple",
  "settings.cancelTerms.googlePlayLink": "Інструкції зі скасування Google Play",
  "settings.cancelTerms.graceTitle": "Після завершення оплаченого періоду — 15 днів пільгового періоду, потім видалення:",
  "settings.cancelTerms.intro": "Це умови платних підписок Luminous StockHaven. Оплата підписки на вебсайті відбувається через Stripe. Ви можете самостійно скасувати підписку будь-коли за допомогою кнопки «Скасувати підписку» нижче — схвалення персоналу не потрібне. Запити на скасування та повернення коштів також можна обробити через офіційний контакт служби підтримки клієнтів: theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Ви можете самостійно скасувати підписку будь-коли. Схвалення персоналу не потрібне. Майбутні продовження припиняються лише після того, як платіжний провайдер підтвердить скасування.",
  "settings.cancelTerms.noApprovalTitle": "Скасування без схвалення:",
  "settings.cancelTerms.paymentBody": "Для платних пробних періодів семиденний пробний період потребує способу оплати під час реєстрації. Якщо не скасувати до відповідного кінцевого строку скасування пробного періоду, вибраний місячний план буде автоматично оплачено після пробного періоду. Ціна, дата першого списання та кінцевий строк скасування, специфічний для провайдера, мають бути показані під час реєстрації. Оплата пробного періоду відбувається через Stripe.",
  "settings.cancelTerms.paymentTitle": "Спосіб оплати та автоматичне продовження:",
  "settings.cancelTerms.remainingBody": "Якщо ви вже сплатили за розрахунковий період, ви можете зберігати доступ до підтвердженої дати, до якої сплачено. Раніше припинення потребує належного підтвердження провайдера та будь-якої необхідної обробки повернення коштів. Доступ у межах безкоштовного пробного періоду завершується відповідно до підтвердженої провайдером дати завершення пробного періоду.",
  "settings.cancelTerms.remainingTitle": "Доступ, що залишився:",
  "settings.cancelTerms.storesBody": "Якщо ви колись оформите підписку через Google Play або Apple App Store, вашу підписку оплачує та нею керує цей магазин. Можливо, вам доведеться скасувати її безпосередньо в розділі підписок того самого облікового запису Google або Apple, який використовувався для підписки. Скасування окремої підписки на вебсайті, видалення цього застосунку або запит на видалення облікового запису Luminous StockHaven не скасовує автоматично підписку, оплачувану через магазин. Перевірте квитанцію про покупку, щоб підтвердити, хто виставляє вам рахунки.",
  "settings.cancelTerms.storesTitle": "Підписки Google Play та Apple App Store (якщо ви колись оформите підписку через магазин):",
  "settings.cancelTerms.title": "Умови та положення скасування",
  "settings.cancelTerms.trialBody": "Семиденний пробний період можна використати лише один раз на відповідного клієнта. Скасування пробного періоду чи підписки не надає ще одного пробного періоду; клієнти, які повертаються, мають вибрати платну підписку.",
  "settings.cancelTerms.trialTitle": "Один безкоштовний пробний період:",
  "settings.canceled.endsOn": "Цю підписку скасовано, і вона завершується {date}. До того часу ви зберігаєте повний доступ.",
  "settings.delete.checking": "Перевірка наявного запиту на видалення…",
  "settings.delete.description": "Запитати видалення вашого облікового запису для входу в Luminous StockHaven.",
  "settings.delete.dialogDescription": "Це запитує перегляд видалення облікового запису. Це не видаляє одразу ваш вхід чи запаси й не скасовує жодної підписки Stripe. Введіть {word}, щоб підтвердити, що ви хочете надіслати запит.",
  "settings.delete.dialogTitle": "Запитати видалення облікового запису",
  "settings.delete.enterDelete": "Введіть {word} для підтвердження",
  "settings.delete.exportFirst": "Спочатку експортуйте свої запаси, якщо вам потрібно зберегти записи.",
  "settings.delete.intro": "Надсилання запиту не видаляє одразу ваш обліковий запис, бізнеси чи запаси. Запити переглядаються окремо, перш ніж видалення можна буде завершити. Цей запит не скасовує підписку Stripe і не зупиняє майбутні списання; скасування підписки потрібно оформлювати окремо через платіжного провайдера.",
  "settings.delete.keepAccount": "Зберегти обліковий запис",
  "settings.delete.noExport": "Essentials не має експорту — запишіть усе потрібне, перш ніж запитувати видалення.",
