  "settings.title": "Налаштування",
  "settings.trial.cancelKeeps": "Скасування під час пробного періоду зберігає ваші повні 7 днів — доступ завершується {date}, і з вас не буде стягнуто плату.",
  "staff.access.noSeatBody": "Ваш обліковий запис не має місця співробітника для цього бізнесу, тож його запаси залишаються закритими. Попросіть власника додати вас у розділі «Персонал і ролі».",
  "staff.access.noSeatTitle": "Цей бізнес не відкритий для вашого входу",
  "staff.access.pendingBody": "Цей бізнес має запрошення для вашої електронної пошти, яке ще не активовано. Попросіть власника встановити ваш статус співробітника на активний. До того часу тут нічого не видно.",
  "staff.access.pendingTitle": "Ваше запрошення ще не активне",
  "staff.access.signOut": "Вийти",
  "staff.access.suspendedBody": "Адміністратор призупинив цей обліковий запис співробітника для активного бізнесу. Попросіть його повернути вам активний статус, а потім увійдіть знову.",
  "staff.access.suspendedTitle": "Ваш доступ призупинено",
  "staff.addFirst": "Додати першого співробітника",
  "staff.addMember": "Додати співробітника",
  "staff.emptyBody": "Додайте людину, надайте їй роль і дозволи, що йдуть із нею, і її буде запрошено електронною поштою увійти до цього бізнесу.",
  "staff.emptyTitle": "Співробітників ще немає",
  "staff.eyebrow": "Команда",
  "staff.how.p1": "Кожен учасник має роль і власний список дозволів, тож ви можете почати з ролі й змінити одну річ, не створюючи нової ролі. Редагування ролі не переписує учасників, які вже на ній, — відкрийте учасника, щоб повторно застосувати типові значення його ролі.",
  "staff.how.p2": "Власні ролі — це функція плану Business: Essentials використовує п'ять вбудованих ролей (Owner, Manager, Stock clerk, Sales clerk, Viewer).",
  "staff.how.p3": "Запрошення надсилаються електронною поштою. Учасник може увійти лише після прийняття, а видалення когось із цього списку не видаляє його обліковий запис у застосунку.",
  "staff.how.p4": "Магазин — це локація, до якої призначено людину. Це записано на її картці; те, що вона може відкривати, досі визначають її роль і дозволи.",
  "staff.how.p5": "Дозволи визначають, що кожна людина може відкривати: пункти меню поза її роллю приховано, а заблокована адреса показує повідомлення «не входить до вашої ролі» замість сторінки. Зміна застосовується наступного разу, коли ця людина завантажить застосунок; призупинення учасника повністю блокує йому доступ.",
  "staff.how.p6": "Адміністратори можуть бачити й змінювати всі дані, керувати користувачами застосунку та ролями й ніколи не обмежуються роллю співробітника. Той, хто не має запису співробітника — власник нового бізнесу — зберігає повний доступ.",
  "staff.howTitle": "Як працюють персонал і ролі",
