  "rewards.void": "Анулювати",
  "rewards.voided": "Нагороду анульовано.",
  "workforce.tab.rewards": "Нагороди",
  "training.lessons.mgr-give-rewards.step1": "Відкрийте «Команда» й торкніться «Нагороди». Виберіть члена команди, потім вид: відсоток знижки в магазині, подарункову картку або щось інше, що ви опишете власними словами.",
  "training.lessons.mgr-give-rewards.step2": "Дайте нагороді коротку назву й нотатку, якщо хочете. Людина одразу отримує дзвіночок, а нагорода чекає в її «Моїх нагородах» із власним кодом.",
  "training.lessons.mgr-give-rewards.step3": "Межа, за задумом: ви нагороджуєте ЛИШЕ ПЕРСОНАЛ. Ви не можете нагородити себе або іншого керівника — нагородження керівника є рішенням власника, і застосунок прямо відмовить у цьому.",
  "training.lessons.mgr-give-rewards.step4": "На касі введіть код, який показує вам член команди, і позначте його використаним — кожен код працює один раз. Ви можете анулювати вручену вами нагороду, якщо плани зміняться; подарунки власника анулює власник.",
  "training.lessons.mgr-give-rewards.title": "Вручення нагород вашому персоналу",
  "training.lessons.owner-give-rewards.step1": "Нагороди живуть у «Команді», на вкладці «Нагороди», і доступні лише на плані Business — на Essentials вкладка показує замкнені двері, щоб ваша команда могла бачити, що містить більший план.",
  "training.lessons.owner-give-rewards.step2": "Ви можете нагородити БУДЬ-КОГО в команді — персонал і керівників однаково. Виберіть людину, потім вид: відсоток знижки в магазині (будь-який відсоток на ваш вибір), подарункову картку куди завгодно або будь-яке заохочення, яке ви опишете власними словами.",
  "training.lessons.owner-give-rewards.step3": "Нагорода надходить із власним одноразовим кодом і дзвонить у дзвіночок людини. Вони показують код на касі; власник або керівник вводить його, щоб позначити використаною.",
  "training.lessons.owner-give-rewards.step4": "Надрукований або надісланий талон нагороди містить ЛИШЕ назву ВАШОГО бізнесу — ніколи назву застосунку. Це подяка вашого магазину, а не реклама.",
  "training.lessons.owner-give-rewards.title": "Вручення нагород (план Business)",
  "training.lessons.owner-rewards-oversight.step1": "Ваш керівник також може вручати нагороди — лише персоналу. Застосунок відмовляє, коли керівник нагороджує себе або іншого керівника; нагородження керівника завжди є вашим рішенням.",
  "training.lessons.owner-rewards-oversight.step2": "Ви бачите кожну нагороду в бізнесі в історії нагород: хто її вручив, хто її отримав і чи вона готова, використана або анульована. Керівник бачить лише нагороди, які він вручив, і ті, які отримав.",
  "training.lessons.owner-rewards-oversight.step3": "Ви можете анулювати будь-яку нагороду, включно з тією, яку вручив ваш керівник. Керівник може анулювати власні подарунки, але ніколи ваші.",
  "training.lessons.owner-rewards-oversight.step4": "Кожен код працює рівно один раз, а анульовану нагороду ніколи не можна використати — історія завжди показує, чим завершилася нагорода.",
  "training.lessons.owner-rewards-oversight.title": "Нагляд за нагородами: вручення вашого керівника",
  "training.lessons.staff-your-rewards.step1": "Коли ваш керівник або власник вручає вам нагороду, ваш дзвіночок дзвонить. Відкрийте «Команда» й торкніться «Нагороди», щоб побачити її в «Моїх нагородах».",
  "training.lessons.staff-your-rewards.step2": "Кожна нагорода має власний код. Тримайте його при собі — той, хто покаже код на касі, і використає нагороду.",
  "training.lessons.staff-your-rewards.step3": "Щоб використати її, покажіть код під час купівлі. Людина на касі вводить його й позначає використаною — кожен код працює рівно один раз.",
  "training.lessons.staff-your-rewards.step4": "Нагороди — це приємність плану Business. Якщо ваш магазин не на Business, вкладка «Нагороди» натомість показує замкнені двері — це план, а не помилка.",
  "training.lessons.staff-your-rewards.title": "Ваші нагороди: знайти код і використати його",
  "training.module.rewards": "Нагороди й заохочення",
