  "pos.toast.restaurantPlaceholder": "GUID ресторану",
  "pos.toast.credentialNote": "Toast видає ці дані через свою партнерську програму. Вони зберігаються лише на сервері і ніколи не показуються назад.",
  "pos.lightspeed.help": "Підключіть свій магазин Lightspeed Retail (X-Series), і кожен завершений продаж сам списуватиме свої товари із запасів тут.",
  "pos.lightspeed.connect": "Підключити Lightspeed",
